#!/usr/bin/env node
/**
 * Phase 5 — NORBIN technical extraction.
 *
 * The grammar was surveyed across the corpus before this parser was written and
 * it is not the R-M/baslac grammar, despite the shared owner. These sheets are
 * generated by BASF's MPV system and have their own shape:
 *
 *   <boilerplate safety advice + legal disclaimer, identical in every sheet>
 *   Technical Information
 *   <product name> / <code> / <product name>
 *   JSON created 2022-01-11T11:09:38+0000, MPV 4.0     ← generator artefact
 *   Application:   2K clear coat for all basecoat finishes.
 *   Key Features:  Medium solid, good hardness, fast drying.
 *   Storage temperature
 *   5-40 °C
 *   Mixing Ratio   2:1  100 % by volume  N15-020 …  Hardener  50 % …  N75-021 …
 *                  HVLP spray gun        Compliant gravity-feed spray gun
 *   Application pressure  bar     2       2
 *   Nozzle size                   1.3     1.3-1.4
 *
 * Three things a naive parser gets wrong here, and what is done instead:
 *
 *  1. The boilerplate is longer than the technical content and repeats in all
 *     24 sheets. Extracted blind it would dominate the claim set, so it is
 *     removed by its own fixed phrases before anything is read.
 *
 *  2. `JSON created …, MPV 4.0` looks exactly like a `Label: value` pair and
 *     appeared 12 times in the label survey. It is a generator stamp, not a
 *     product fact.
 *
 *  3. The application table has one column per spray-gun type. Most rows carry
 *     two values (`Nozzle size 1.3 1.3-1.4`) but some carry one
 *     (`Nozzle pressure bar 0.7`). Splitting two values across the two guns is
 *     correct; guessing which gun a single value belongs to is not, so those
 *     stay unscoped and are flagged.
 *
 * Mixing-ratio blocks name the hardeners by code, which is the manufacturer
 * stating a product↔component relationship explicitly. Those are captured as
 * relationships rather than flattened into text.
 *
 * Output: data/knowledge/norbin-tds-claims.generated.json
 */

import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import path from "node:path";
import { extractPdfBatch } from "./lib/rm-pdf-text.mjs";

const documents = JSON.parse(readFileSync("data/knowledge/norbin-documents.generated.json", "utf8"));
const generatedAt = new Date().toISOString();
const TEXT_CACHE = ".cache/norbin/tds-text.json";

const sheets = documents.documents.filter(
  (entry) => entry.documentType === "tds" && entry.localPath && !entry.error && existsSync(entry.localPath),
);

/** Cache is a speed-up, not an input. */
function buildCache() {
  const byPath = new Map();
  const BATCH = 30;
  for (let index = 0; index < sheets.length; index += BATCH) {
    const slice = sheets.slice(index, index + BATCH);
    for (const result of extractPdfBatch(slice.map((entry) => entry.localPath))) {
      byPath.set(result.path, result);
    }
  }
  return sheets.map((entry) => {
    const result = byPath.get(entry.localPath);
    return { ...entry, ok: result?.ok !== false, pages: result?.pages ?? [] };
  });
}

let docs;
if (existsSync(TEXT_CACHE)) {
  docs = JSON.parse(readFileSync(TEXT_CACHE, "utf8"));
} else {
  docs = buildCache();
  mkdirSync(path.dirname(TEXT_CACHE), { recursive: true });
  writeFileSync(TEXT_CACHE, JSON.stringify(docs));
}

/* -------------------------------------------------------------------------- */
/* Cleaning                                                                   */
/* -------------------------------------------------------------------------- */

/**
 * The extractor breaks words at kerning pairs — "af\nfect", "Y\nou",
 * "flash of\nf". Rejoining them keeps values like "flash off" searchable.
 */
function repairLineBreaks(text) {
  return text.replace(/([a-zA-ZäöüÄÖÜşğıİ])\n([a-zäöüşğıİ])/g, "$1$2");
}

/** Boilerplate present in every sheet; never a product fact. */
const BOILERPLATE = [
  /The data contained in this publication are based on our current knowledge/i,
  /Any descriptions, drawings, photographs, data, proportions/i,
  /The latest version supersedes all previous versions/i,
  /You can obtain the latest version from our/i,
  /It is the responsibility of the recipient of our products/i,
  /Bu yayında yer alan veriler mevcut bilgi ve deneyimlerimize dayanmaktadır/i,
  /Ürünlerimizin işlenmesini ve uygulanmasını etkileyebilecek/i,
  /^page \d+ of \d+$/i,
  /JSON created .*MPV/i,
  /^\.$/,
];

const isBoilerplate = (line) => BOILERPLATE.some((pattern) => pattern.test(line));

/* -------------------------------------------------------------------------- */
/* Labels — English and Turkish                                               */
/* -------------------------------------------------------------------------- */

const LABEL_MAP = [
  { re: /^(application|uygulama|kullanım alanı)$/i, field: "intendedUse" },
  { re: /^(key features|özellikler|features)$/i, field: "keyFeatures" },
  { re: /^(storage temperature|depolama sıcaklığı|saklama sıcaklığı)$/i, field: "storageTemperature" },
  { re: /^(shelf life|raf ömrü)$/i, field: "shelfLife" },
  { re: /^(mixing ratio|karışım oranı)$/i, field: "mixingRatio" },
  { re: /^(spray viscosity.*|püskürtme viskozitesi.*)$/i, field: "sprayViscosity" },
  { re: /^(pot ?life.*|kap ömrü.*)$/i, field: "potLife" },
  { re: /^(application pressure|uygulama basıncı)$/i, field: "sprayPressure" },
  { re: /^(nozzle pressure|meme basıncı)$/i, field: "nozzlePressure" },
  { re: /^(nozzle size|meme çapı|meme ölçüsü)$/i, field: "nozzleSize" },
  { re: /^(number of spray coats|kat sayısı|püskürtme kat sayısı)$/i, field: "sprayCoats" },
  { re: /^(flash off.*|flash-off.*|ara kuruma.*)$/i, field: "flashOffTime" },
  { re: /^(film thickness|film kalınlığı|kuru film kalınlığı)$/i, field: "filmThickness" },
  { re: /^(drying.*|kuruma.*|kurutma.*)$/i, field: "dryingTime" },
  { re: /^(sanding|zımpara|zımparalama)$/i, field: "sandability" },
  { re: /^(suitable surfaces|uygun yüzeyler|uygun kullanım yüzeyleri)$/i, field: "substrate" },
  { re: /^(total hardness|toplam sertlik)$/i, field: "hardness" },
  { re: /^(voc.*)$/i, field: "voc" },
  { re: /^(colou?r|renk)$/i, field: "colour" },
  { re: /^(please note|lütfen göz önünde bulundurunuz|remarks|notlar)$/i, field: "note" },
];

const typeOf = (label) => LABEL_MAP.find((entry) => entry.re.test(label.trim()))?.field;

/* -------------------------------------------------------------------------- */
/* Values                                                                     */
/* -------------------------------------------------------------------------- */

const UNIT_RE = /(µm|μm|°C|bar|min\.?|hours?|h\b|months?|ay\b|s\b|%|g\s*\/\s*l|mm)/i;
const QUALIFIER_RE = /(approx\.?|about|ca\.|up to|min\.|max\.|>|<|≥|≤|±)/i;
const NEGATION_RE = /\b(not|no|never|do not|without|nicht|kein|değil|olmaz)\b/i;
const RESTRICTION_RE = /\b(not suitable|do not (use|apply)|never apply|must not|uygun değildir)\b/i;

function parseValue(raw) {
  const text = String(raw).trim();
  const conditionMatch = /\(([^)]{2,90})\)\s*$/.exec(text);
  const condition = conditionMatch ? conditionMatch[1].trim() : undefined;
  const withoutCondition = conditionMatch ? text.slice(0, conditionMatch.index).trim() : text;

  const numeric = [...withoutCondition.matchAll(/-?\d+(?:[.,]\d+)?/g)].map((match) =>
    Number(match[0].replace(",", ".")),
  );
  const isRange = /\d\s*[-–—]\s*\d/.test(withoutCondition) && numeric.length >= 2;

  return {
    value: withoutCondition,
    condition,
    unit: UNIT_RE.exec(withoutCondition)?.[1]?.replace(/\s+/g, ""),
    qualifier: QUALIFIER_RE.exec(withoutCondition)?.[1],
    range: isRange ? { min: Math.min(...numeric), max: Math.max(...numeric) } : undefined,
    negative: NEGATION_RE.test(text),
    restriction: RESTRICTION_RE.test(text),
  };
}

const CODE_RE = /\bN\d{2}-[A-Z0-9]{3}\b/g;

/* -------------------------------------------------------------------------- */

const records = [];

for (const document of docs) {
  const claims = [];
  const relationships = [];

  (document.pages ?? []).forEach((pageText, pageIndex) => {
    const lines = repairLineBreaks(pageText)
      .split("\n")
      .map((line) => line.replace(/\s+$/, ""))
      .filter((line) => line.trim() && !isBoilerplate(line.trim()));

    /**
     * Column headers are read from the document, never assumed. The English
     * sheets pair "HVLP spray gun" with "Compliant gravity-feed spray gun";
     * the Turkish ones pair "HVLP tabanca" with "Konvansiyonel tabanca" — a
     * *conventional* gun, which is not the same equipment. Hardcoding the
     * English label would have mislabelled every Turkish row.
     */
    const gunHeaderIndex = lines.findIndex((line) => /\bHVLP\b/i.test(line));
    let gunColumns = [];
    if (gunHeaderIndex >= 0) {
      const header = lines
        .slice(gunHeaderIndex, gunHeaderIndex + 4)
        .map((line) => line.trim())
        .filter(Boolean);
      const joined = header.join(" ").replace(/\s+/g, " ");
      const second = /(Compliant[^|]*?gun|Konvansiyonel\s+tabanca|Conventional[^|]*?gun)/i.exec(joined)?.[1];
      if (second) {
        gunColumns = [/HVLP\s*(spray gun|tabanca)?/i.exec(joined)?.[0]?.trim() ?? "HVLP", second.trim()];
      }
    }
    const inEquipmentTable = gunColumns.length === 2;

    const push = (claim) =>
      claims.push({
        ...claim,
        page: pageIndex + 1,
        sourceType: "manufacturer-technical-document",
        documentFileName: document.fileName,
        documentSha256: document.sha256,
        documentSourceUrl: document.sourceUrl,
        status: "machine-extracted",
      });

    /** A known label, with or without a trailing colon. */
    const labelAt = (line) => {
      const bare = line.replace(/:\s*$/, "").trim();

      // The condition split is tried first. "Spray viscosity at 20°C" also
      // matches the plain `spray viscosity.*` pattern, so checking that first
      // would swallow the temperature and state the value unconditionally.
      const withCondition = /^(.*?)\s+(at\s+[\d.,]+\s*°C|bei\s+[\d.,]+\s*°C|[\d.,]+\s*°C['\u2019]?\s*de)$/i.exec(bare);
      if (withCondition) {
        const inner = LABEL_MAP.find((candidate) => candidate.re.test(withCondition[1].trim()));
        if (inner) return { field: inner.field, label: bare, condition: withCondition[2].trim() };
      }

      const entry = LABEL_MAP.find((candidate) => candidate.re.test(bare));
      return entry ? { field: entry.field, label: bare, condition: undefined } : undefined;
    };

    const isSeparator = (line) => !line || line === "." || /^[\s.]*$/.test(line);
    const EQUIPMENT_FIELDS = new Set(["sprayPressure", "nozzlePressure", "nozzleSize", "sprayCoats", "flashOffTime", "filmThickness"]);
    const VALUE_LINE = /^[\d<>≤≥]|^(ready|approx|ca\.|min|max)/i;

    for (let index = 0; index < lines.length; index += 1) {
      const line = lines[index].trim();

      // -- Label: value on one line ---------------------------------------
      const inline = /^([A-Za-zÄÖÜäöüşğıİ][A-Za-zÄÖÜäöüşğıİ0-9 .,%/()°-]{2,45}?):\s*(\S.{0,200})$/.exec(line);
      if (inline && !isBoilerplate(inline[2])) {
        const parsed = parseValue(inline[2]);
        const field = typeOf(inline[1]);
        push({
          field: field ?? "otherSpecification",
          sourceLabel: inline[1].trim(),
          ...parsed,
          excerpt: line.slice(0, 220),
          extractionConfidence: field ? "high" : "medium",
        });
        continue;
      }

      const matched = labelAt(line);
      if (!matched) continue;

      /**
       * The mixing-ratio block names its hardeners by code — the manufacturer
       * declaring a component relationship rather than us inferring one. The
       * ratio itself is printed on the line *above* the label.
       */
      if (matched.field === "mixingRatio") {
        const block = lines.slice(Math.max(0, index - 1), index + 9).join(" ");
        const codes = [...new Set(block.match(CODE_RE) ?? [])].filter((code) => code !== document.code);
        const ratio = /\b\d+\s*:\s*\d+\b/.exec(block)?.[0];
        for (const code of codes) {
          relationships.push({
            type: "mixes-with",
            partnerCode: code,
            ratio,
            evidence: block.slice(0, 200),
            page: pageIndex + 1,
            sourceType: "manufacturer-technical-document",
            status: "machine-extracted",
          });
        }
        push({
          field: "mixingRatio",
          sourceLabel: matched.label,
          value: ratio ?? lines[index + 1]?.trim(),
          partnerCodes: codes,
          excerpt: block.slice(0, 220),
          extractionConfidence: ratio ? "high" : "medium",
        });
        continue;
      }

      /**
       * The application table prints one column per spray-gun type, laid out
       * as: label, optional unit, then one value per column.
       *
       *   Application pressure / bar / 2 / 2      → 2 bar for both guns
       *   Nozzle pressure     / bar / 0.7         → one value, two columns
       *
       * Two values map onto the two guns unambiguously. One value does not say
       * which gun it belongs to, so it stays unscoped and is flagged rather
       * than assigned to both.
       */
      if (EQUIPMENT_FIELDS.has(matched.field) && inEquipmentTable) {
        let cursor = index + 1;
        const unit = lines[cursor] && /^(µm|μm|bar|min|s|%|°C)\s*$/i.test(lines[cursor].trim())
          ? lines[cursor++].trim()
          : undefined;

        const values = [];
        while (cursor < lines.length && values.length < gunColumns.length) {
          const candidate = lines[cursor].trim();
          if (isSeparator(candidate) || labelAt(candidate) || !VALUE_LINE.test(candidate)) break;
          values.push(candidate);
          cursor += 1;
        }
        if (!values.length) continue;

        if (values.length === gunColumns.length) {
          values.forEach((value, column) => {
            const parsed = parseValue(value);
            push({
              field: matched.field,
              sourceLabel: matched.label,
              ...parsed,
              condition: parsed.condition ?? matched.condition,
              unit: parsed.unit ?? unit,
              applicationEquipment: gunColumns[column],
              excerpt: `${matched.label} ${unit ?? ""} ${values.join(" / ")}`.trim().slice(0, 220),
              extractionConfidence: "high",
            });
          });
        } else {
          const parsed = parseValue(values.join(" "));
          push({
            field: matched.field,
            sourceLabel: matched.label,
            ...parsed,
            condition: parsed.condition ?? matched.condition,
            unit: parsed.unit ?? unit,
            equipmentScopeAmbiguous: true,
            excerpt: `${matched.label} ${unit ?? ""} ${values.join(" ")}`.trim().slice(0, 220),
            extractionConfidence: "medium",
          });
        }
        index = cursor - 1;
        continue;
      }

      // -- Bare label, value on the following line -------------------------
      let cursor = index + 1;
      while (cursor < lines.length && isSeparator(lines[cursor].trim())) cursor += 1;
      let next = lines[cursor]?.trim();
      if (!next || isBoilerplate(next) || labelAt(next)) continue;

      /**
       * Some rows interpose the measurement standard between the label and its
       * value:
       *
       *   Spray viscosity at 20°C
       *   DIN 4:            ← method, not the value
       *   16-18 s           ← the value
       *
       * Taking the first following line would record "DIN 4:" as the viscosity.
       */
      let method;
      if (/^[A-Za-z][A-Za-z0-9 .\/-]{1,20}:\s*$/.test(next) && !/\d\s*(s|min|h|°C|bar|µm|μm)\b/i.test(next)) {
        method = next.replace(/:\s*$/, "").trim();
        cursor += 1;
        while (cursor < lines.length && isSeparator(lines[cursor].trim())) cursor += 1;
        next = lines[cursor]?.trim();
        if (!next || isBoilerplate(next) || labelAt(next)) continue;
      }

      const parsed = parseValue(next);
      push({
        field: matched.field,
        sourceLabel: matched.label,
        ...parsed,
        condition: parsed.condition ?? matched.condition,
        measurementMethod: method,
        // An equipment value read outside the two-column table has no column to
        // belong to. It is marked rather than left silently unscoped.
        equipmentScopeAmbiguous: EQUIPMENT_FIELDS.has(matched.field) ? true : undefined,
        excerpt: `${line}${method ? ` ${method}:` : ""} ${next}`.slice(0, 220),
        extractionConfidence: EQUIPMENT_FIELDS.has(matched.field) ? "medium" : "high",
      });
      index = cursor;
    }
  });

  records.push({
    documentFileName: document.fileName,
    documentSha256: document.sha256,
    documentSourceUrl: document.sourceUrl,
    code: document.code,
    availability: document.availability,
    regions: document.regions,
    pageCount: (document.pages ?? []).length,
    claims,
    relationships,
  });
}

const allClaims = records.flatMap((record) => record.claims);
const byField = {};
for (const claim of allClaims) byField[claim.field] = (byField[claim.field] ?? 0) + 1;

const summary = {
  generatedAt,
  brand: "NORBIN",
  manufacturer: "BASF Coatings GmbH",
  sourceType: "manufacturer-technical-document",
  documentsProcessed: records.length,
  documentsWithClaims: records.filter((record) => record.claims.length).length,
  documentsWithoutClaims: records.filter((record) => !record.claims.length).length,
  totalClaims: allClaims.length,
  typedClaims: allClaims.filter((claim) => claim.field !== "otherSpecification").length,
  byField,
  withCondition: allClaims.filter((claim) => claim.condition).length,
  withRange: allClaims.filter((claim) => claim.range).length,
  withUnit: allClaims.filter((claim) => claim.unit).length,
  negative: allClaims.filter((claim) => claim.negative).length,
  restrictions: allClaims.filter((claim) => claim.restriction).length,
  withPageEvidence: allClaims.filter((claim) => typeof claim.page === "number").length,
  withMeasurementMethod: allClaims.filter((claim) => claim.measurementMethod).length,
  equipmentScoped: allClaims.filter((claim) => claim.applicationEquipment).length,
  distinctEquipmentColumns: [...new Set(allClaims.map((claim) => claim.applicationEquipment).filter(Boolean))],
  equipmentAmbiguous: allClaims.filter((claim) => claim.equipmentScopeAmbiguous).length,
  relationships: records.reduce((total, record) => total + record.relationships.length, 0),
  distinctSourceLabels: new Set(allClaims.map((claim) => claim.sourceLabel)).size,
  // Proof the boilerplate filter works: the disclaimer is longer than the
  // technical content and would otherwise dominate.
  boilerplateClaims: allClaims.filter((claim) =>
    /current knowledge and experience|supersedes all previous/i.test(String(claim.value)),
  ).length,
};

mkdirSync("data/knowledge", { recursive: true });
writeFileSync(
  "data/knowledge/norbin-tds-claims.generated.json",
  `${JSON.stringify({ summary, records }, null, 2)}\n`,
);

console.log(JSON.stringify(summary, null, 2));
